examples.template:
VStack(alignment: .leading, spacing: 8) {
    Toggle(isOn: $updates) {
        VStack(alignment: .leading, spacing: 2) {
            Text({{items.0.label}})
            Text({{items.0.description}}).monarchTextStyle(.caption)
        }
    }
    .toggleStyle(.monarchCheckbox)
    Toggle(sources: [$partOne, $partTwo], isOn: \.self) {
        Text({{items.1.label}})
    }
    .toggleStyle(.monarchCheckbox)
    Toggle({{items.2.label}}, isOn: .constant(false))
        .toggleStyle(.monarchCheckbox)
        .disabled({{items.2.disabled}})
}

examples.setupTemplate:
@State private var updates = {{items.0.checked}}
@State private var partOne = {{items.1.indeterminate}}
@State private var partTwo = false

examples.setup:
@State private var updates = true
@State private var partOne = true
@State private var partTwo = false

examples.code:
VStack(alignment: .leading, spacing: 8) {
    Toggle(isOn: $updates) {
        VStack(alignment: .leading, spacing: 2) {
            Text("Email me updates")
            Text("About once a month.").monarchTextStyle(.caption)
        }
    }
    .toggleStyle(.monarchCheckbox)
    Toggle(sources: [$partOne, $partTwo], isOn: \.self) {
        Text("Select all")
    }
    .toggleStyle(.monarchCheckbox)
    Toggle("Unavailable", isOn: .constant(false))
        .toggleStyle(.monarchCheckbox)
        .disabled(true)
}
